import { ToyRoomBattle } from '../src/js/toy-room/ToyRoomBattle.js';
import { ARENA_ENEMIES } from '../src/js/toy-room/ArenaEnemies.js';
import { ARENA_TUNING, ArenaPlayerController } from '../src/js/toy-room/ArenaPlayerController.js';
import { arenaEnemyContact } from '../src/js/toy-room/ArenaCombatContact.js';
function simulate(interval, direction, cooldown = 24) {
  const room = {player:{x:430,facing:'right',animTime:0},keysDown:{},gamepadState:{},touchState:{},tutorial:{},furniture:[],clearInput(){this.keysDown={};},story:{state:{swordEquipped:true,attackElapsed:0},attack(){if(this.state.attackElapsed>0)return false;this.state.attackElapsed=12;this.state.attackDirection=room.player.facing==='left'?-1:1;return true;}}};
  const b=new ToyRoomBattle(room,{loadAssets:false});b.tuning={...ARENA_TUNING,swordCooldown:cooldown};b.playerController=new ArenaPlayerController();b.presentation={enemies:ARENA_ENEMIES,enemyContact:arenaEnemyContact};b.activate();
  const metrics={};let frames=0;
  const original=b.setEnemyState.bind(b);
  b.setEnemyState=(next)=>{const e=b.state.enemy,m=metrics[e.actor]??={cancelados:0,iniciados:0};if(next==='HIT'&&e.state==='ATTACK')m.cancelados++;if(next==='ATTACK')m.iniciados++;original(next);};
  for(;frames<18000&&b.state.mode==='BATTLE';frames++){
    if(!b.state.transition){const toward=direction==='fixa'?1:(b.state.enemy.x>=room.player.x?1:-1);room.keysDown=toward>0?{ArrowRight:true}:{ArrowLeft:true};if(frames%interval===0)b.attack();}
    b.update(1);
  }
  for(const actor of ['train','robot','dinosaur','bear']){const m=metrics[actor]??={cancelados:0,iniciados:0};m.acertos=b.state.history.filter(x=>x.event==='PLAYER_HIT'&&x.enemy===actor).length;m.danos=b.state.history.filter(x=>x.event==='ENEMY_HIT'&&x.enemy===actor).length;}
  return {intervalo:interval,direcao:direction,cooldown,resultado:b.state.mode,quadros:frames,segundos:+(frames/60).toFixed(2),hp:b.state.player.hp,metrics};
}
for(const direction of ['fixa','acompanha'])for(const interval of [1,6,12,24])console.log(JSON.stringify(simulate(interval,direction)));
for(const cooldown of [36,48,60])console.log(JSON.stringify(simulate(1,'acompanha',cooldown)));
console.log('Auditoria concluída: simulação sem render, movimento e espada reais; nenhuma esquiva; variantes de cooldown somente em memória.');
